package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import java.util.zip.ZipOutputStream;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_read_TriageGen1Test {

    @Test(expected = IOException.class)
    public void testRead_WhenClosed() throws IOException {
        byte[] zipData = createZipData("test", "hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();
        zais.close();

        byte[] buffer = new byte[10];
        zais.read(buffer, 0, 10);
    }

    @Test
    public void testRead_WhenFinishedOrNullEntry() throws IOException {
        byte[] zipData = createZipData("test", "hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));

        // Case: current == null (no entry selected yet)
        byte[] buffer = new byte[10];
        Assert.assertEquals(-1, zais.read(buffer, 0, 10));

        // Case: inf.finished() (after reading all entries)
        zais.getNextZipEntry();
        zais.read(buffer, 0, 5);
        // Exhaust entry and stream
        while (zais.getNextZipEntry() != null);

        Assert.assertEquals(-1, zais.read(buffer, 0, 10));
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_InvalidBufferBounds() throws IOException {
        byte[] zipData = createZipData("test", "hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();

        byte[] buffer = new byte[5];
        // start > buffer.length
        zais.read(buffer, 10, 1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_NegativeStart() throws IOException {
        byte[] zipData = createZipData("test", "hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();

        byte[] buffer = new byte[10];
        zais.read(buffer, -1, 5);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_NegativeLength() throws IOException {
        byte[] zipData = createZipData("test", "hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();

        byte[] buffer = new byte[10];
        zais.read(buffer, 0, -1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_LengthOverflowsBuffer() throws IOException {
        byte[] zipData = createZipData("test", "hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();

        byte[] buffer = new byte[10];
        // start + length > buffer.length
        zais.read(buffer, 5, 6);
    }

    @Test
    public void testRead_DeflatedContent() throws IOException {
        byte[] zipData = createZipData("deflated", "hello world");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));

        ZipArchiveEntry entry = zais.getNextZipEntry();
        Assert.assertNotNull(entry);

        byte[] buffer = new byte[5];
        int read = zais.read(buffer, 0, 5);
        Assert.assertEquals(5, read);
        Assert.assertEquals("hello", new String(buffer, 0, 5));
    }

    @Test
    public void testRead_StoredContent() throws IOException {
        // To test STORED method, we must create a ZIP with STORED entries
        byte[] zipData = createStoredZipData("stored", "hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));

        ZipArchiveEntry entry = zais.getNextZipEntry();
        Assert.assertNotNull(entry);
        // Note: In actual Commons Compress, the entry type is determined by header

        byte[] buffer = new byte[2];
        int read = zais.read(buffer, 0, 2);
        Assert.assertEquals(2, read);
        Assert.assertEquals("he", new String(buffer, 0, 2));

        // Read more to trigger offsetInBuffer logic
        int read2 = zais.read(buffer, 0, 2);
        Assert.assertEquals(2, read2);
        Assert.assertEquals("ll", new String(buffer, 0, 2));

        // Read remaining
        int read3 = zais.read(buffer, 0, 2);
        Assert.assertEquals(1, read3);
        Assert.assertEquals("o", new String(buffer, 0, 1));

        // End of stored entry
        Assert.assertEquals(-1, zais.read(buffer, 0, 1));
    }

    private byte[] createZipData(String name, String content) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry(name);
            zos.putNextEntry(entry);
            zos.write(content.getBytes());
            zos.closeEntry();
        }
        return baos.toByteArray();
    }

    private byte[] createStoredZipData(String name, String content) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry(name);
            // Force STORED method
            entry.setMethod(ZipEntry.STORED);
            entry.setSize(content.length());
            entry.setCrc(java.util.zip.CRC32.calculate(content.getBytes()));
            zos.putNextEntry(entry);
            zos.write(content.getBytes());
            zos.closeEntry();
        }
        return baos.toByteArray();
    }
}
